"""Temporary model for verifying database migrations."""

from datetime import datetime

from sqlalchemy import DateTime, func
from sqlalchemy.orm import Mapped, mapped_column

from optometry.db.base import Base


class SchemaCheck(Base):
    """Simple table used to verify Alembic migrations."""

    __tablename__ = "schema_check"

    # Primary key automatically generated by PostgreSQL.
    id: Mapped[int] = mapped_column(primary_key=True)

    # Database generates the creation timestamp.
    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True),
        server_default=func.now(),
        nullable=False,
    )
